package com.francisco.mifactur
import android.app.*
import android.content.*
import android.database.sqlite.*
import android.graphics.*
import android.graphics.pdf.PdfDocument
import android.os.*
import android.view.*
import android.widget.*
import com.google.zxing.BarcodeFormat
import com.google.zxing.qrcode.QRCodeWriter
import java.io.*
import java.math.BigDecimal
import java.math.RoundingMode
import java.text.SimpleDateFormat
import java.util.*
private fun bd(s:String)=BigDecimal(s.replace(',','.').ifBlank{"0"})
private fun r(v:BigDecimal)=v.setScale(2,RoundingMode.HALF_UP)
private fun eur(v:BigDecimal)=r(v).toPlainString().replace('.',',')+" €"
data class Client(val id:Long,val name:String,val nif:String)
data class L(val id:Long,val invoiceId:Long,val desc:String,val qty:BigDecimal,val price:BigDecimal,val vatRate:BigDecimal,val base:BigDecimal,val vat:BigDecimal)
data class Inv(val id:Long,val no:String,val date:String,val client:String,val nif:String,val irpfRate:BigDecimal,val base:BigDecimal,val vat:BigDecimal,val irpf:BigDecimal,val total:BigDecimal)
class MainActivity:Activity(){private lateinit var db:Db;private lateinit var body:LinearLayout;private var exportData="";private var exportType="application/xml"
 override fun onCreate(b:Bundle?){super.onCreate(b);db=Db(this);home()}
 private fun shell(t:String){val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(22,26,22,18)};root.addView(TextView(this).apply{text="MI_FACTUR";textSize=28f;setTextColor(Color.rgb(11,107,203))});val nav=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};listOf("Inicio","Clientes","Facturas").forEach{n->nav.addView(Button(this).apply{text=n;setOnClickListener{when(n){"Inicio"->home();"Clientes"->clients();else->invoices()}}},LinearLayout.LayoutParams(0,-2,1f))};root.addView(nav);root.addView(TextView(this).apply{text=t;textSize=21f;setPadding(0,14,0,8)});body=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(body)},LinearLayout.LayoutParams(-1,0,1f));setContentView(root)}
 private fun home(){shell("Resumen");body.addView(TextView(this).apply{text="Clientes: ${db.clients().size}\nFacturas: ${db.invs().size}";textSize=20f});body.addView(btn("+ Cliente"){clientDialog()});body.addView(btn("+ Factura"){invoiceDialog()})}
 private fun clients(){shell("Clientes");body.addView(btn("+ Nuevo cliente"){clientDialog()});db.clients().forEach{c->body.addView(TextView(this).apply{text="${c.name} · ${c.nif}";textSize=17f;setPadding(8,14,8,14)})}}
 private fun clientDialog(){val f=form();val n=input("Nombre/Razón social");val nif=input("NIF/CIF");f.addView(n);f.addView(nif);AlertDialog.Builder(this).setTitle("Nuevo cliente").setView(f).setPositiveButton("Guardar"){_,_->if(n.text.isNotBlank()){db.addClient(n.text.toString(),nif.text.toString());clients()}}.setNegativeButton("Cancelar",null).show()}
 private fun invoiceDialog(){val cs=db.clients();if(cs.isEmpty()){toast("Crea primero un cliente");return};val f=form();val sp=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,cs.map{it.name})};val irpf=input("IRPF %","15");val linesBox=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val lines=mutableListOf<Array<EditText>>();fun add(){val d=input("Descripción");val q=input("Cantidad","1");val p=input("Precio");val v=input("IVA %","21");linesBox.addView(TextView(this).apply{text="Línea ${lines.size+1}"});listOf(d,q,p,v).forEach{linesBox.addView(it)};lines+=arrayOf(d,q,p,v)};f.addView(sp);f.addView(irpf);f.addView(linesBox);add();f.addView(btn("+ Línea"){add()});val scroll=ScrollView(this).apply{addView(f)};AlertDialog.Builder(this).setTitle("Nueva factura").setView(scroll).setPositiveButton("Guardar"){_,_->try{val parsed=lines.map{arrayOf(it[0].text.toString(),it[1].text.toString(),it[2].text.toString(),it[3].text.toString())};db.addInv(cs[sp.selectedItemPosition],bd(irpf.text.toString()),parsed);invoices()}catch(e:Exception){toast("Revisa líneas e importes")}}.setNegativeButton("Cancelar",null).show()}
 private fun invoices(){shell("Facturas");body.addView(btn("+ Nueva factura"){invoiceDialog()});db.invs().forEach{i->val ls=db.lines(i.id);val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(12,12,12,12);setBackgroundColor(Color.rgb(245,247,250))};box.addView(TextView(this).apply{text="${i.no} · ${i.date}\n${i.client}\n"+ls.joinToString("\n"){"• ${it.desc}: ${it.qty} × ${eur(it.price)} · IVA ${it.vatRate}%"}+"\nBase ${eur(i.base)} · IVA ${eur(i.vat)} · IRPF -${eur(i.irpf)}\nTOTAL ${eur(i.total)}";textSize=15f});val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};row.addView(btn("PDF"){pdf(i,ls)},LinearLayout.LayoutParams(0,-2,1f));row.addView(btn("XML"){xml(i,ls)},LinearLayout.LayoutParams(0,-2,1f));box.addView(row);body.addView(box,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,0,0,12)})}}
 private fun qrUrl(i:Inv)="https://www2.agenciatributaria.gob.es/wlpl/TIKE-CONT/ValidarQR?nif=${enc(i.nif)}&numserie=${enc(i.no)}&fecha=${enc(i.date)}&importe=${i.total.setScale(2,RoundingMode.HALF_UP).toPlainString()}"
 private fun enc(s:String)=java.net.URLEncoder.encode(s,"UTF-8")
 private fun qr(s:String):Bitmap{val m=QRCodeWriter().encode(s,BarcodeFormat.QR_CODE,180,180);return Bitmap.createBitmap(180,180,Bitmap.Config.RGB_565).apply{for(y in 0 until 180)for(x in 0 until 180)setPixel(x,y,if(m[x,y])Color.BLACK else Color.WHITE)}}
 private fun pdf(i:Inv,ls:List<L>){val doc=PdfDocument();val pg=doc.startPage(PdfDocument.PageInfo.Builder(595,842,1).create());val c=pg.canvas;val p=Paint(1);fun text(s:String,y:Float,z:Float=12f){p.color=Color.BLACK;p.textSize=z;c.drawText(s,45f,y,p)};text("MI_FACTUR - FACTURA",50f,24f);text("Factura ${i.no} · ${i.date}",85f,15f);text("Cliente: ${i.client} · ${i.nif}",110f);var y=155f;ls.forEach{text("${it.desc}  ${it.qty} x ${eur(it.price)}  IVA ${it.vatRate}%",y);y+=25};text("Base: ${eur(i.base)}",y+20);text("IVA: ${eur(i.vat)}",y+45);text("IRPF (${i.irpfRate}%): -${eur(i.irpf)}",y+70);text("TOTAL: ${eur(i.total)}",y+105,18f);val bm=qr(qrUrl(i));c.drawBitmap(bm,null,RectF(365f,625f,545f,805f),p);text("QR tributario",365f+0,11f);doc.finishPage(pg);val file=File(cacheDir,"${i.no}.pdf");FileOutputStream(file).use{doc.writeTo(it)};doc.close();val data=FileInputStream(file).readBytes();exportBytes("${i.no}.pdf",data,"application/pdf")}
 private fun xml(i:Inv,ls:List<L>){fun e(s:String)=s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");val rows=ls.joinToString(""){"<Linea><Descripcion>${e(it.desc)}</Descripcion><Cantidad>${it.qty}</Cantidad><Precio>${it.price.setScale(2,RoundingMode.HALF_UP)}</Precio><TipoIVA>${it.vatRate}</TipoIVA><Base>${it.base.setScale(2,RoundingMode.HALF_UP)}</Base><CuotaIVA>${it.vat.setScale(2,RoundingMode.HALF_UP)}</CuotaIVA></Linea>"};val x="<?xml version=\"1.0\" encoding=\"UTF-8\"?><Factura><Numero>${e(i.no)}</Numero><Fecha>${e(i.date)}</Fecha><Cliente><Nombre>${e(i.client)}</Nombre><NIF>${e(i.nif)}</NIF></Cliente><Lineas>$rows</Lineas><Base>${i.base.setScale(2,RoundingMode.HALF_UP)}</Base><IVA>${i.vat.setScale(2,RoundingMode.HALF_UP)}</IVA><IRPF>${i.irpf.setScale(2,RoundingMode.HALF_UP)}</IRPF><Total>${i.total.setScale(2,RoundingMode.HALF_UP)}</Total><QR>${e(qrUrl(i))}</QR></Factura>";exportBytes("${i.no}.xml",x.toByteArray(),"application/xml")}
 private fun exportBytes(name:String,data:ByteArray,type:String){exportData=android.util.Base64.encodeToString(data,android.util.Base64.NO_WRAP);exportType=type;startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);this.type=type;putExtra(Intent.EXTRA_TITLE,name)},77)}
 override fun onActivityResult(r:Int,c:Int,d:Intent?){super.onActivityResult(r,c,d);if(r==77&&c==RESULT_OK)d?.data?.let{uri->contentResolver.openOutputStream(uri)?.use{it.write(android.util.Base64.decode(exportData,android.util.Base64.NO_WRAP))};toast("Archivo guardado")}}
 private fun form()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,8,24,0)};private fun input(h:String,v:String="")=EditText(this).apply{hint=h;setText(v);setPadding(10,10,10,10)};private fun btn(t:String,a:()->Unit)=Button(this).apply{text=t;setOnClickListener{a()}};private fun toast(t:String)=Toast.makeText(this,t,Toast.LENGTH_LONG).show()}
class Db(c:Context):SQLiteOpenHelper(c,"mifactur3.db",null,1){override fun onCreate(d:SQLiteDatabase){d.execSQL("CREATE TABLE clients(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,nif TEXT)");d.execSQL("CREATE TABLE invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,no TEXT,date TEXT,client_id INTEGER,irpf_rate TEXT,base TEXT,vat TEXT,irpf TEXT,total TEXT)");d.execSQL("CREATE TABLE lines(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_id INTEGER,desc TEXT,qty TEXT,price TEXT,vat_rate TEXT,base TEXT,vat TEXT)")};override fun onUpgrade(d:SQLiteDatabase,a:Int,b:Int){}
 fun addClient(n:String,nif:String){writableDatabase.execSQL("INSERT INTO clients(name,nif) VALUES(?,?)",arrayOf(n,nif))};fun clients():List<Client>{val r=mutableListOf<Client>();readableDatabase.rawQuery("SELECT id,name,nif FROM clients",null).use{while(it.moveToNext())r+=Client(it.getLong(0),it.getString(1),it.getString(2)?:"")};return r}
 fun addInv(c:Client,rr:BigDecimal,raw:List<Array<String>>){val ls=raw.map{val q=bd(it[1]);val p=bd(it[2]);val vr=bd(it[3]);val b=r(q*p);val v=r(b*vr/BigDecimal("100"));arrayOf(it[0],q.toPlainString(),p.toPlainString(),vr.toPlainString(),b.toPlainString(),v.toPlainString())};val base=r(ls.fold(BigDecimal.ZERO){a,l->a+bd(l[4])});val vat=r(ls.fold(BigDecimal.ZERO){a,l->a+bd(l[5])});val irpf=r(base*rr/BigDecimal("100"));val total=r(base+vat-irpf);val no="F-${Calendar.getInstance().get(Calendar.YEAR)}-${String.format(Locale.US,"%04d",invs().size+1)}";val date=SimpleDateFormat("dd-MM-yyyy",Locale.US).format(Date());val d=writableDatabase;d.beginTransaction();try{val cv=ContentValues().apply{put("no",no);put("date",date);put("client_id",c.id);put("irpf_rate",rr.toPlainString());put("base",base.toPlainString());put("vat",vat.toPlainString());put("irpf",irpf.toPlainString());put("total",total.toPlainString())};val id=d.insertOrThrow("invoices",null,cv);ls.forEach{l->d.execSQL("INSERT INTO lines(invoice_id,desc,qty,price,vat_rate,base,vat) VALUES(?,?,?,?,?,?,?)",arrayOf(id,l[0],l[1],l[2],l[3],l[4],l[5]))};d.setTransactionSuccessful()}finally{d.endTransaction()}}
 fun invs():List<Inv>{val r=mutableListOf<Inv>();readableDatabase.rawQuery("SELECT i.id,i.no,i.date,c.name,c.nif,i.irpf_rate,i.base,i.vat,i.irpf,i.total FROM invoices i JOIN clients c ON c.id=i.client_id ORDER BY i.id DESC",null).use{while(it.moveToNext())r+=Inv(it.getLong(0),it.getString(1),it.getString(2),it.getString(3),it.getString(4)?:"",bd(it.getString(5)),bd(it.getString(6)),bd(it.getString(7)),bd(it.getString(8)),bd(it.getString(9)))};return r};fun lines(id:Long):List<L>{val out=mutableListOf<L>();readableDatabase.rawQuery("SELECT id,invoice_id,desc,qty,price,vat_rate,base,vat FROM lines WHERE invoice_id=?",arrayOf("$id")).use{while(it.moveToNext())out+=L(it.getLong(0),it.getLong(1),it.getString(2),bd(it.getString(3)),bd(it.getString(4)),bd(it.getString(5)),bd(it.getString(6)),bd(it.getString(7)))};return out}}
